using Avalonia;
using Avalonia.Controls;
using Avalonia.Layout;
using Avalonia.Media;

namespace AiTranslate.Desktop;

/// <summary>
/// Pictogrammers Material Design Icons (https://pictogrammers.com/library/mdi/) vector icon control.
/// Every icon in AI Translate uses official 24x24 MDI SVG path data per AGENTS.md.
/// </summary>
public sealed class MdiIcon : Control
{
    public static readonly StyledProperty<string> IconNameProperty =
        AvaloniaProperty.Register<MdiIcon, string>(nameof(IconName), "translate");

    public static readonly StyledProperty<IBrush?> ForegroundProperty =
        AvaloniaProperty.Register<MdiIcon, IBrush?>(nameof(Foreground), Brushes.White);

    public static readonly StyledProperty<double> IconSizeProperty =
        AvaloniaProperty.Register<MdiIcon, double>(nameof(IconSize), 18.0);

    public string IconName
    {
        get => GetValue(IconNameProperty);
        set => SetValue(IconNameProperty, value);
    }

    public IBrush? Foreground
    {
        get => GetValue(ForegroundProperty);
        set => SetValue(ForegroundProperty, value);
    }

    public double IconSize
    {
        get => GetValue(IconSizeProperty);
        set => SetValue(IconSizeProperty, value);
    }

    static MdiIcon()
    {
        AffectsRender<MdiIcon>(IconNameProperty, ForegroundProperty, IconSizeProperty);
        AffectsMeasure<MdiIcon>(IconSizeProperty);
    }

    public MdiIcon()
    {
        HorizontalAlignment = HorizontalAlignment.Center;
        VerticalAlignment = VerticalAlignment.Center;
    }

    public MdiIcon(string iconName, double size = 18.0, IBrush? foreground = null) : this()
    {
        IconName = iconName;
        IconSize = size;
        if (foreground is not null)
            Foreground = foreground;
    }

    protected override Size MeasureOverride(Size availableSize)
    {
        var s = Math.Max(8, IconSize);
        return new Size(s, s);
    }

    public override void Render(DrawingContext context)
    {
        if (Foreground is null) return;
        var geometry = MdiIconLibrary.GetGeometry(IconName);
        var targetSize = Math.Max(8, IconSize);
        var scale = targetSize / 24.0;
        var offsetX = (Bounds.Width - targetSize) / 2.0;
        var offsetY = (Bounds.Height - targetSize) / 2.0;

        var matrix = Matrix.CreateScale(scale, scale) * Matrix.CreateTranslation(offsetX, offsetY);
        using (context.PushTransform(matrix))
        {
            context.DrawGeometry(Foreground, null, geometry);
        }
    }
}

